defmodule WithDecimalWeb.Endpoint do
  use Phoenix.Endpoint, otp_app: :with_decimal

  # Serves the OpenAPI document and its interface, generated by Portolan.
  plug Plug.Static, at: "/", from: :with_decimal, only: ~w(openapi.json openapi.html)

  if code_reloading? do
    plug Phoenix.CodeReloader
  end

  plug Plug.Parsers,
    parsers: [:urlencoded, :json],
    pass: ["*/*"],
    json_decoder: Phoenix.json_library()

  plug WithDecimalWeb.Router
end
